import{_ as n,l as s,o as e,c as l,v as t,p as i,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"下推自动机","description":"","frontmatter":{"title":"下推自动机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pushdown-automata.md","filePath":"cs/pushdown-automata.md","lastUpdated":1789023840000}'),h={name:"cs/pushdown-automata.md"};function m(D,a,A,C,u,F){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="下推自动机" tabindex="-1">下推自动机 <a class="header-anchor" href="#下推自动机" aria-label="Permalink to &quot;下推自动机&quot;">​</a></h1><div class="epigraph"><p>有限控制加上一根栈：读输入、换栈顶，恰好认上下文无关语言；确定下推机严格更弱。</p><footer>—— 据 Chomsky, 1962；Hopcroft and Ullman；Sipser 整理</footer></div><p>上一课<a href="/cs/regular-closure">正则封闭性</a>把 3 型语言的运算收齐，并指出 CFL 不再对补、交关闭。主干<a href="/cs/cfg-grammar">CFG</a>已有产生式与推导树，但机器一侧还停在 DFA。缺口是<strong>下推自动机（PDA）</strong>：给 CFG 配上栈，并登记与 2 型等价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>括号匹配、\\(a^nb^n\\) 需要记住尚未关闭的计数，有限状态不够，无限计数器又太强。栈是折中：只动顶端。PDA：\\(\\delta(q,a,X)\\) 给出有限个 \\((p,\\gamma)\\)，用 \\(\\gamma\\) 替换栈顶 \\(X\\)；\\(a\\) 可以是 \\(\\varepsilon\\)。接受：读完输入且栈空，或进入接受态——两种定义等价（可互译）。</p><p>CFG \\(\\to\\) PDA：用栈模拟最左推导。PDA \\(\\to\\) CFG：变量记「从 \\(p\\) 带着栈底 \\(X\\) 走到 \\(q\\) 且弹出 \\(X\\)」。本课要等价的形状，不把构造的每一条产生式写完。</p><h3 id="确定-pda-不是「dfa-加栈」那么强" tabindex="-1">确定 PDA 不是「DFA 加栈」那么强 <a class="header-anchor" href="#确定-pda-不是「dfa-加栈」那么强" aria-label="Permalink to &quot;确定 PDA 不是「DFA 加栈」那么强&quot;">​</a></h3><p>DPDA 的语言类 DCFL 真包含于 CFL：\\(\\{ww^R\\}\\) 是 CFL 经典例子，确定机难以在中点翻栈。编程语言的 LR 家族落在 DCFL 附近；一般 CFG 需要非确定或更重的分析。主干<a href="/cs/lr-shift-reduce">LR</a>用移进归约，直觉就是确定栈，本课不重做分析表。</p><p><span class="marginnote">Chomsky 把 CFG 与「下推」对应。Sipser 用接受态定义；Hopcroft–Ullman 常强调空栈接受。非确定是语言类的一部分，不是实现 bug。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画认 \\(a^nb^n\\) 的 PDA：读 \\(a\\) 压栈，读 \\(b\\) 弹栈，恰空则接受。指出交 \\(a^nb^nc^n\\) 需要两条独立计数，单栈做不到——这为泵引理课埋伏。乘积机对 PDA 不保 CFL：栈无法同时维护两套无关符号。</p>',11)),(e(),i(c,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%20%E4%BA%A7%E7%94%9F%E5%BC%8F%22%5D%20--%3E%20PDA%5B%22%E9%9D%9E%E7%A1%AE%E5%AE%9A%20PDA%22%5D%0A%20%20PDA%20--%3E%20CFL%5B%22%E5%90%8C%E4%B8%80%E7%B1%BB%20CFL%22%5D%0A%20%20PDA%20--%3E%20DET%5B%22DPDA%20%2F%20DCFL%20%E6%9B%B4%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>正则是 PDA 不真正用栈（或栈高有界）的特例。不要把 PDA 写成图灵机的「只许用栈」限制——图灵机还没有定义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>栈给出后进先出的嵌套，对应推导树的递归。二义 CFG 对应多条接受路，不是多根栈。 \\(\\varepsilon\\) 转移用于结束推导、弹出剩余；词法课的 \\(\\varepsilon\\) 边同一语法，对象换成栈符号。</p><p>CFL 对并、连接、星封闭（文法侧显然），对交、补不封闭（与 \\(a^nb^n\\cap a^nb^nc^n\\) 相关）。本课点名，证明细节可放到泵引理之后。</p><p>栈符号表是有限的，无穷来自栈高。这与计数器机器不同：计数器没有「把符号埋住再挖出」的名字，只有整数。CFG 的递归非终结符对应压栈；\\(\varepsilon\\) 产生式对应弹空。确定 PDA 的语言对补封闭，一般 CFL 不——这是 DCFL 真小的另一面。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CYK，不证 \\(a^nb^nc^n\\) 非 CFL（下一课泵）。不引入双栈机器——双栈已经图灵完全，那是后课。后课默认：CFL \\(=\\) 非确定 PDA 的语言；DCFL 真小。下一课给 CFL 负向引理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PDA = 有限控制 + 栈，与 CFG 认同一类。</li><li>非确定本质；DPDA 更弱。</li><li>单栈不能同时维护两套独立计数。</li><li>出处：Chomsky；Hopcroft and Ullman；Sipser。</li></ul>',9))])}const f=n(h,[["render",m]]);export{_ as __pageData,f as default};
